"""Reviewed, bounded examples for both senior-school programmes."""


def author(packet, numeric, reasoning, F, fmt):
    def rows(v, items):
        for family, item in enumerate(items, 1):
            numeric(family, v, *item)
    def opens(items):
        for family, (prompt, solution, hint, claims, rubric) in enumerate(items, 9):
            reasoning(family, prompt, solution, hint, claims, rubric,
                      ['error','methods','counterexample','insufficient'][family-9])

    packet('10-201','percent estimation','fractions','Записывайте проценты множителем и сохраняйте точные дроби до последнего шага. Укажите правило округления и единицы результата.')
    for v in (1,2):
        p=10+5*v;n=200+100*v
        rows(v,[
            (f'Найдите {p}% от {n}.',n*p//100,f'{p}%={p}/100, поэтому {n}·{p}/100={n*p//100}.','Представьте процент долей единицы.',f'x*100=={n}*{p}'),
            (f'{n*p//100} составляет {p}% числа. Найдите число.',n,f'Искомое число равно {n*p//100}:({p}/100)={n}. Проверка: его {p}% равны {n*p//100}.','Разделите часть на долю.',f'x*{p}=={n*p}'),
            (f'Округлите {v+2},376 до сотых.',F((v+2)*100+38,100),f'Цифра тысячных 6, поэтому сотые увеличиваются: {v+2},38.','Посмотрите на первую отбрасываемую цифру.',f'x==F({(v+2)*100+38},100) and abs(x-F({(v+2)*1000+376},1000))<F(5,1000)'),
            (f'Цена {n} рублей выросла на 20%, затем снизилась на 20%. Найдите итоговую цену.',F(n*96,100),f'Множители 1,2 и 0,8 дают 0,96. Цена {n}·0,96={fmt(F(n*96,100))} руб.','Второе изменение считается от новой цены.',f'x=={n}*F(6,5)*F(4,5)'),
            (f'После скидки 25% товар стоит {3*n//4} рублей. Найдите прежнюю цену.',n,f'Осталось 75% цены: {3*n//4}:0,75={n} руб.','Восстанавливайте целое по оставшейся доле.',f'x*F(3,4)=={3*n//4}'),
            (f'Точное число {v+2},376 заменили числом {v+2},38. Найдите абсолютную погрешность.',F(1,250),'Модуль разности приближённого и точного значений равен 0,004.','Абсолютная погрешность — модуль разности.',f'x==abs(F({(v+2)*100+38},100)-F({(v+2)*1000+376},1000))'),
            (f'Для ремонта нужно {v+2},4 м провода. Его продают целыми метрами. Сколько метров следует купить?',v+3,f'Покупка {v+2} м недостаточна. Ближайшее целое сверху — {v+3} м.','Точность покупки должна обеспечивать достаточную длину.',f'x-1<F({10*(v+2)+4},10)<=x'),
            (f'На {n} рублей купили товар со скидкой 20%. Какова экономия относительно полной цены этой покупки?',n//4,f'Полная цена {n}:0,8={5*n//4} руб. Экономия {5*n//4}−{n}={n//4} руб.','Сначала восстановите цену до скидки.',f'({n}+x)*F(4,5)=={n}')])
    opens([
        ('Ученик считает, что рост цены на 10% и снижение на 10% возвращают прежнюю цену. Исправьте вывод.','Множители 1,1 и 0,9 дают 0,99. Например, цена 100 становится 110, затем 99. Итог на 1% ниже исходного.','У процентов разные основания.',['100*F(11,10)*F(9,10)==99'],['Названы два последовательных множителя.','Проверен пример 100 → 110 → 99.','Верно описано итоговое изменение.']),
        ('Найдите 15% от 240 двумя способами.','Первый способ: 240·0,15=36. Второй: 10% равны 24, 5% — 12; сумма 36. Разложение 15%=10%+5% сохраняет общее основание 240.','Разложите процент на удобные части.',['240*F(15,100)==36','24+12==36'],['Показано умножение на долю.','Использованы 10% и 5% одного числа.','Объяснено совпадение результатов.']),
        ('Опровергните: «Округление всегда увеличивает число».','Число 2,31 при округлении до десятых превращается в 2,3, то есть уменьшается. Направление зависит от первой отбрасываемой цифры.','Возьмите отбрасываемую цифру меньше 5.',['F(23,10)<F(231,100)'],['Указана точность округления.','Округление выполнено верно.','Получено уменьшение числа.']),
        ('Цена выросла на 20 рублей. Достаточно ли этого для определения процента роста?','Нет. Рост со 100 до 120 равен 20%, а с 200 до 220 — 10%. Нужна исходная цена.','Сравните одинаковую прибавку с разными основаниями.',['F(20,100)*100==20','F(20,200)*100==10'],['Даны два допустимых исходных значения.','Вычислены разные проценты роста.','Названо недостающее основание.'])])

    packet('10-204','domain root-selection radicals','quadratic-equation','Перед возведением в квадрат проверьте неотрицательность правой части. После преобразования подставьте кандидатов в исходное уравнение.')
    for v in (1,2):
        a=v+2;r=v+3
        rows(v,[
            (f'Решите √(x+{a})={r}.',r*r-a,f'Обе части неотрицательны. x+{a}={r*r}, поэтому x={r*r-a}. Под корнем получается {r*r}.','Возведите равенство в квадрат.',f'x+{a}=={r*r} and {r}>=0'),
            (f'Найдите наименьшее допустимое x в выражении √(x−{a}).',a,f'Подкоренное выражение должно быть неотрицательным: x≥{a}. Минимум {a}.','Учитывайте ноль под корнем.',f'x-{a}==0'),
            (f'Сколько действительных корней имеет √(x+{a})=−{r}?',0,'Арифметический корень неотрицателен, правая часть отрицательна. Равенство невозможно.','Сравните знаки сторон до вычислений.',f'x==0 and -{r}<0'),
            (f'Решите √(x+{a})=√({2*a+1}).',a+1,f'Равенство корней равносильно равенству неотрицательных подкоренных выражений: x+{a}={2*a+1}. Ответ {a+1}.','Обе части — арифметические корни.',f'x+{a}=={2*a+1} and x+{a}>=0'),
            (f'Найдите больший корень √((x−{a})²)={r}.',a+r,f'Слева |x−{a}|. Корни {a-r} и {a+r}, больший {a+r}.','Корень из квадрата равен модулю.',f'abs(x-{a})=={r} and x>{a}'),
            (f'Найдите сумму корней √((x−{a})²)={r}.',2*a,f'Корни {a}±{r} симметричны относительно {a}; их сумма {2*a}.','Учтите обе ветви модуля.',f'x==({a}-{r})+({a}+{r})'),
            (f'Сторона квадратного участка равна √(S) метров. Найдите площадь S, если сторона {r} м.',r*r,f'S≥0 и √S={r}, поэтому S={r*r} м². Подстановка восстанавливает положительную сторону.','Площадь квадрата равна квадрату стороны.',f'x=={r}**2 and x>=0'),
            (f'Модель скорости v=√(2s) задана при s≥0. При каком s скорость равна {2*r}?',2*r*r,f'Из √(2s)={2*r} получаем 2s={4*r*r}, s={2*r*r}. Значение неотрицательно.','Проверьте допустимость полученного пути.',f'2*x=={2*r}**2 and x>=0')])
    opens([
        ('Ученик решил √(x+2)=x и оставил корни −1 и 2. Найдите ошибку.','Правая часть требует x≥0. Квадратное уравнение x²−x−2=0 даёт −1 и 2, но −1 не подходит: √1=1≠−1. Корень только 2.','Проверьте знак правой части.',['(-1)**2==-1+2','2**2==2+2','-1<0','2>=0'],['Записано ограничение x≥0.','Обнаружен посторонний корень −1.','Подтверждён корень 2.']),
        ('Решите √((x−3)²)=2 двумя способами.','Через модуль: |x−3|=2, x=1 или 5. Через квадрат: (x−3)²=4 с разложением разности квадратов даёт те же корни. Оба подходят исходному корню.','Используйте модуль и разность квадратов.',['abs(1-3)==abs(5-3)==2','(1-3)**2==(5-3)**2==4'],['Рассмотрены обе ветви модуля.','Показано квадратное преобразование.','Проверены два исходных корня.']),
        ('Опровергните: «Возведение уравнения в квадрат никогда не добавляет корней».','Уравнение √x=−1 не имеет корней, но после возведения в квадрат получается x=1. При x=1 исходная левая часть равна 1, а правая −1.','Квадрат теряет знак.',['1**2==(-1)**2','1!=-1'],['Дано исходное уравнение без корней.','Получен кандидат после квадратирования.','Проверено, что он посторонний.']),
        ('Известно только, что после возведения обеих частей в квадрат получилось x=4. Можно ли утверждать, что исходное уравнение имеет корень 4?','Нет. Уравнения √x=2 и √x=−2 после квадратирования дают x=4, но во втором исходное равенство невозможно. Нужна исходная запись со знаками.','Сравните противоположные правые части.',['2**2==(-2)**2==4','2!=-2'],['Приведены два исходных уравнения.','Показано одинаковое следствие.','Объяснена необходимость проверки знаков.'])])

    packet('10-213','sequences linear-equation','operations','Используйте номер члена как число шагов от первого: aₙ=a₁+(n−1)d. В обратной задаче проверьте целочисленность и положительность номера.')
    for v in (1,2):
        a=3+v;d=2+v
        rows(v,[
            (f'В арифметической прогрессии a₁={a}, d={d}. Найдите a₆.',a+5*d,f'От первого до шестого члена пять шагов: {a}+5·{d}={a+5*d}.','Различайте номер и количество шагов.',f'x==sum([{a},{d},{d},{d},{d},{d}])'),
            (f'В арифметической прогрессии a₁={a}, a₆={a+5*d}. Найдите d.',d,f'Разность между членами {5*d} распределена на 5 шагов, d={d}.','Вычислите число промежутков.',f'{a}+5*x=={a+5*d}'),
            (f'В арифметической прогрессии d={d}, a₆={a+5*d}. Найдите a₁.',a,f'Возвращаемся на пять шагов: {a+5*d}−5·{d}={a}.','Вычтите прирост за пять шагов.',f'x+5*{d}=={a+5*d}'),
            (f'a₁={a}, d={d}. Какой номер имеет член {a+7*d}?',8,f'(n−1)·{d}={7*d}, поэтому n−1=7, n=8. Номер — положительное целое.','Найдите число шагов, затем прибавьте 1.',f'{a}+(x-1)*{d}=={a+7*d} and x>=1'),
            (f'Найдите сумму первых 6 членов арифметической прогрессии a₁={a}, d={d}.',6*a+15*d,f'a₆={a+5*d}; сумма 6·({a}+{a+5*d})/2={6*a+15*d}.','Попарно сложите крайние члены.',f'x==ap_sum({a},{d},6)'),
            (f'В арифметической прогрессии a₃={a+2*d}, a₇={a+6*d}. Найдите a₁.',a,f'Между данными членами четыре шага, d={d}. Затем a₁=a₃−2d={a}.','Сначала восстановите разность.',f'{a+2*d}-x==2*F({4*d},4)'),
            (f'В первом ряду {a+10} мест, каждый следующий содержит на {d} больше. Сколько мест в пятом ряду?',a+10+4*d,f'Добавление происходит четыре раза: {a+10}+4·{d}={a+10+4*d}.','Это арифметическая прогрессия по рядам.',f'x=={a+10}+4*{d}'),
            (f'За первый день прочитано {a} страниц, затем ежедневно на {d} страниц больше. Сколько страниц прочитано за 6 дней?',6*a+15*d,f'Дневные объёмы образуют прогрессию. Сумма первых 6 равна {6*a+15*d}, а не объёму шестого дня.','Нужна сумма, а не последний член.',f'x==ap_sum({a},{d},6)')])
    opens([
        ('Ученик использовал aₙ=a₁+nd. Исправьте формулу и проверьте при n=1.','От первого члена до n-го n−1 переходов, поэтому aₙ=a₁+(n−1)d. При n=1 прибавка нулевая. Ошибочная формула даёт a₁+d вместо a₁ при d≠0.','Начните с первого члена.',['4+(1-1)*3==4','4+1*3!=4'],['Посчитаны переходы.','Записана правильная формула.','Выполнена проверка при n=1.']),
        ('Найдите сумму 2+5+8+11 двумя способами.','Прямое сложение даёт 26. Попарное сложение крайних: (2+11)+(5+8)=13+13=26. Равенство пар следует из постоянной разности 3.','Сопоставьте крайние члены.',['2+5+8+11==26','2+11==5+8==13'],['Показано прямое сложение.','Составлены пары с одинаковой суммой.','Связь объяснена постоянной разностью.']),
        ('Опровергните: «Любая арифметическая прогрессия возрастает».','Прогрессия 5,3,1,−1,… имеет разность −2 и убывает. Знак разности определяет направление изменения.','Возьмите отрицательную разность.',['3-5==1-3==-1-1==-2'],['Приведены члены прогрессии.','Проверена постоянная отрицательная разность.','Указано убывание.']),
        ('Известно a₅=10. Можно ли восстановить арифметическую прогрессию?','Нет. При d=0 все члены равны 10. При d=1 первый член равен 6, и пятый тоже 10. Нужна ещё одна независимая характеристика.','Измените разность и восстановите первый член.',['10+4*0==6+4*1==10'],['Построены две разные прогрессии.','В обеих проверен пятый член.','Указана недостаточность одного значения.'])])

    packet('10-222','mean median','operations','Перед вычислением характеристики определите размер и порядок выборки. Выброс влияет на среднее, а медиана определяется центральными позициями.')
    for v in (1,2):
        a=4+v;b=a+2;c=a+4
        rows(v,[
            (f'Найдите среднее выборки {a}, {b}, {c}.',b,f'Сумма {3*b} делится на 3, среднее {b}.','Учитывайте каждое наблюдение.',f'x==weighted_mean([{a},{b},{c}],[1,1,1])'),
            (f'Найдите медиану выборки {c}, {a}, {b}.',b,f'После сортировки: {a}, {b}, {c}. Центральный элемент {b}.','Сначала упорядочьте выборку.',f'x==median_value([{c},{a},{b}])'),
            (f'Найдите размах выборки {a}, {b}, {c}.',4,f'Размах — максимум минус минимум: {c}−{a}=4.','Число наблюдений не входит в формулу размаха.',f'x==max([{a},{b},{c}])-min([{a},{b},{c}])'),
            (f'К каждому числу выборки {a}, {b}, {c} прибавили 5. Найдите новое среднее.',b+5,f'Сумма выросла на 15 при том же размере 3, поэтому среднее выросло на 5 и стало {b+5}.','Проследите изменение суммы и размера.',f'x==weighted_mean([{a+5},{b+5},{c+5}],[1,1,1])'),
            (f'К выборке {a}, {b}, {c} добавили число {b+12}. Найдите новое среднее.',b+3,f'Новая сумма {4*b+12}, размер 4. Среднее {b+3}.','После добавления изменяется знаменатель.',f'4*x=={a}+{b}+{c}+{b+12}'),
            (f'В выборке {a}, {b}, {c} наибольшее значение заменили числом 100. Найдите новую медиану.',b,f'Порядок {a}<{b}<100 сохраняется. Средний по позиции элемент остаётся {b}.','Медиана зависит от порядка, а не величины крайнего выброса.',f'x==median_value([{a},{b},100])'),
            (f'Два класса: в первом 10 учеников со средним баллом {a}, во втором 20 со средним {a+3}. Найдите средний балл всех учеников.',a+2,f'Общая сумма баллов 10·{a}+20·{a+3}, число учеников 30. Среднее {a+2}.','Взвесьте средние по численности.',f'x==weighted_mean([{a},{a+3}],[10,20])'),
            (f'Пять доставок длились {a}, {b}, {b}, {c}, 100 минут. Найдите медианное время.',b,f'Упорядоченный ряд уже дан. Третье из пяти значений равно {b} минут; задержка 100 минут не меняет центральное значение.','Для пяти значений нужна третья позиция.',f'x==median_value([{a},{b},{b},{c},100])')])
    opens([
        ('Ученик нашёл медиану ряда 1,9,2 как 9, потому что число записано посередине. Исправьте.','Нужно сначала упорядочить ряд: 1,2,9. Медиана равна 2. Исходный порядок записи не определяет центральную позицию по величине.','Отсортируйте наблюдения.',['median_value([1,9,2])==2'],['Ряд упорядочен правильно.','Выбрана центральная позиция.','Объяснена ошибка исходного порядка.']),
        ('Найдите среднее 98,100,102 прямым способом и через отклонения от 100.','Сумма 300, среднее 100. Отклонения −2,0,2 суммируются в 0, поэтому среднее равно выбранному центру 100.','Сумма отклонений от среднего равна нулю.',['F(98+100+102,3)==100','-2+0+2==0'],['Вычислено прямое среднее.','Найдены три отклонения.','Нулевая сумма связана со средним.']),
        ('Опровергните: «Среднее всегда совпадает с медианой».','У выборки 1,2,9 медиана 2, среднее 4. Большое крайнее значение сдвигает среднее.','Используйте несимметричный ряд.',['median_value([1,2,9])==2','F(1+2+9,3)==4'],['Приведена одна выборка.','Верно вычислены обе характеристики.','Показано их несовпадение.']),
        ('Средний балл группы равен 4. Можно ли узнать количество учеников, получивших 4?','Нет. Выборка 4,4 даёт двух таких учеников, а 3,5 — ни одного. Среднее в обоих случаях 4.','Сохраняйте среднее при замене наблюдений.',['F(4+4,2)==F(3+5,2)==4'],['Выбраны выборки одинакового размера.','Проверено одинаковое среднее.','Количество четвёрок различается.'])])

    packet('10-302','polynomials','brackets','Остаток при делении P(x) на x−a равен P(a). Для связей корней сначала приведите квадратный многочлен к стандартному виду и учтите старший коэффициент.')
    for v in (1,2):
        a=2+v;b=5+v;s=a+b;p=a*b
